SELECT CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END AS event_cohort, event_type, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, COUNT(duration_sec) AS duration_sec_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values FROM web_events WHERE session_id IN (13, 16, 37) GROUP BY CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END, event_type HAVING ROUND(AVG(duration_sec), 2) > 69 ORDER BY avg_duration_sec;
